const samples = await IO.loadMNIST();
const K = 10;
if (samples.length < K) throw new Error("At least 10 MNIST images are required");

const kmeans = Kmeans.new(samples, K, {maxIterations: 20}).fit();
const means = Array.from({length: K}, () => new Float32Array(28 * 28));
const counts = new Array(K).fill(0);
for (const sample of samples) {
    const cluster = kmeans.predictIndex(sample);
    counts[cluster]++;
    for (let i = 0; i < sample.length; i++) means[cluster][i] += sample[i];
}
for (let cluster = 0; cluster < K; cluster++) {
    if (counts[cluster] === 0) {
        console.warn(`Cluster ${cluster} is empty`);
        continue;
    }
    for (let i = 0; i < means[cluster].length; i++) means[cluster][i] /= counts[cluster];
}
IO.paintMNIST(means, 5);
